        String displayName=contact.optString("display_name","Conversation");String initial=displayName.isEmpty()?"S":displayName.substring(0,1).toUpperCase(java.util.Locale.getDefault());TextView avatar=SereinUi.avatar(this,initial,42);avatar.setBackground(SereinUi.shape(this,SereinUi.accent(this),21));LinearLayout.LayoutParams avatarParams=SereinUi.margin(this,42,42,1,0,10,0);top.addView(avatar,avatarParams);
        LinearLayout titleBox=SereinUi.column(this);TextView title=SereinUi.text(this,displayName,17,SereinUi.text(this),true);title.setMaxLines(1);titleBox.addView(title);status=SereinUi.text(this,"Preparing secure messaging…",11,SereinUi.muted(this),false);status.setMaxLines(1);status.setEllipsize(android.text.TextUtils.TruncateAt.END);titleBox.addView(status);top.addView(titleBox,new LinearLayout.LayoutParams(0,-2,1));
        Button info=SereinUi.button(this,"ⓘ",false);info.setContentDescription("Contact profile and shared media");top.addView(info,new LinearLayout.LayoutParams(dp(42),dp(42)));info.setOnClickListener(v->showContactProfile());Button keys=SereinUi.button(this,"🔒",false);keys.setContentDescription("View and verify encryption keys");top.addView(keys,new LinearLayout.LayoutParams(dp(42),dp(42)));keys.setOnClickListener(v->showPeerKeys());root.addView(top);
        FrameLayout chatArea=new FrameLayout(this);messageScroll=new ScrollView(this);messageScroll.setFillViewport(false);messageScroll.setBackground(new SereinChatWallpaper(this));messageScroll.setOnTouchListener((view,event)->{if(event.getAction()==android.view.MotionEvent.ACTION_DOWN&&emojiPanelVisible)toggleEmojiPanel();return false;});messages=new LinearLayout(this);messages.setOrientation(LinearLayout.VERTICAL);messages.setPadding(dp(10),dp(8),dp(10),dp(8));messageScroll.addView(messages);chatArea.addView(messageScroll,new FrameLayout.LayoutParams(-1,-1));
