    @Override public void onBackPressed(){if(emojiPanelVisible){toggleEmojiPanel();return;}super.onBackPressed();}
    private void sendText(){if(contact!=null&&contact.optBoolean("deleted")){toast("This archived conversation is read-only.");return;}String text=composer.getText().toString().trim();if(text.isEmpty())return;send.setEnabled(false);status.setText("Encrypting separately for verified recipient devices…");engine.sendText(text).whenComplete((ignored,error)->runOnUiThread(()->{send.setEnabled(!contact.optBoolean("deleted"));if(error!=null)status.setText(safeError(error));else{composer.setText("");status.setText(engine.status());}render();}));}
    private void pickFile(){if(contact!=null&&contact.optBoolean("deleted")){toast("This archived conversation is read-only.");return;}if(engine==null||!engine.ready()){toast("Secure messaging is still starting.");return;}Intent pick=new Intent(Intent.ACTION_OPEN_DOCUMENT);pick.addCategory(Intent.CATEGORY_OPENABLE);pick.setType("*/*");pickFileIntent(pick);}
    private void pickFileIntent(Intent intent){try{startActivityForResult(intent,PICK_FILE);}catch(Exception error){toast("No file picker is available on this device.");}}
    @Override protected void onActivityResult(int requestCode,int resultCode,Intent data){super.onActivityResult(requestCode,resultCode,data);if(requestCode!=PICK_FILE||resultCode!=RESULT_OK||data==null||data.getData()==null)return;Uri uri=data.getData();String name=displayName(uri);String type=SereinChatEngine.mimeType(this,uri,name);stageAndUploadAttachment(uri,name,type,null);}
    private void receiveKeyboardContent(InputContentInfo content,String mime,boolean permissionGranted){runOnUiThread(()->{if(contact==null||contact.optBoolean("deleted")||engine==null||!engine.ready()){if(permissionGranted)try{content.releasePermission();}catch(Exception ignored){}toast("Secure messaging is not ready for this GIF or image.");return;}String name=displayName(content.getContentUri());if(name==null||name.trim().isEmpty()||"attachment".equals(name))name="image/gif".equalsIgnoreCase(mime)?"keyboard.gif":"keyboard-image";stageAndUploadAttachment(content.getContentUri(),name,mime,permissionGranted?content:null);});}
    private void stageAndUploadAttachment(Uri uri,String name,String type,InputContentInfo permission){if(engine==null||!engine.ready()){toast("Secure messaging is still starting.");if(permission!=null)try{permission.releasePermission();}catch(Exception ignored){}return;}status.setText("Preparing encrypted file transfer…");attach.setEnabled(false);
        CompletableFuture.supplyAsync(()->{File staged=null;try{staged=File.createTempFile("serein-upload-",".bin",getCacheDir());long copied=0;try(InputStream in=getContentResolver().openInputStream(uri);FileOutputStream out=new FileOutputStream(staged)){if(in==null)throw new java.io.IOException("Selected file could not be opened.");byte[] buffer=new byte[64*1024];int n;while((n=in.read(buffer))!=-1){copied+=n;if(copied>SereinDeviceCrypto.MAX_FILE_CIPHERTEXT_BYTES)throw new java.io.IOException("Selected file exceeds the 64 MiB encrypted-transfer limit.");out.write(buffer,0,n);}out.flush();out.getFD().sync();}return staged;}catch(Exception error){if(staged!=null)staged.delete();throw new java.util.concurrent.CompletionException(error);}finally{if(permission!=null)try{permission.releasePermission();}catch(Exception ignored){}}}).thenCompose(file->engine.uploadAttachment(file,name,type).whenComplete((ignored,error)->file.delete())).whenComplete((ignored,error)->runOnUiThread(()->{attach.setEnabled(!contact.optBoolean("deleted"));status.setText(error==null?engine.status():safeError(error));render();}));
    }
    private LinearLayout buildEmojiPanel(){LinearLayout panel=new LinearLayout(this);panel.setOrientation(LinearLayout.VERTICAL);panel.setPadding(dp(7),dp(6),dp(7),dp(6));panel.setBackgroundColor(SereinUi.surface(this));LinearLayout mediaActions=SereinUi.row(this);Button gif=SereinUi.button(this,"Browse GIFs",false);gif.setOnClickListener(v->showNekosGifPicker());mediaActions.addView(gif,new LinearLayout.LayoutParams(0,dp(40),1));Button local=SereinUi.button(this,"Attach file",false);local.setOnClickListener(v->pickFile());mediaActions.addView(local,new LinearLayout.LayoutParams(0,dp(40),1));panel.addView(mediaActions);String[] emojis={"😀","😃","😄","😁","😆","😅","😂","🙂","🙃","😉","😊","😍","🥰","😘","😋","😎","🤔","🥳","😴","😭","😡","🤗","🤩","🤝","👋","🙌","👏","👍","👎","👌","✌️","🤞","🙏","💪","❤️","🧡","💛","💚","💙","💜","🖤","🤍","💔","💕","💖","💯","🔥","✨","🎉","🎂","☕","🍕","🌈","🌻","🐱","🐶","🦋","🌍","🚀","🎵"};ScrollView scroll=new ScrollView(this);LinearLayout rows=new LinearLayout(this);rows.setOrientation(LinearLayout.VERTICAL);for(int offset=0;offset<emojis.length;offset+=8){LinearLayout row=new LinearLayout(this);for(int i=offset;i<Math.min(offset+8,emojis.length);i++){final String emoji=emojis[i];Button option=SereinUi.button(this,emoji,false);option.setTextSize(23);option.setPadding(0,0,0,0);option.setContentDescription("Insert "+emoji);option.setOnClickListener(v->insertEmoji(emoji));row.addView(option,new LinearLayout.LayoutParams(0,dp(42),1));}rows.addView(row,new LinearLayout.LayoutParams(-1,-2));}scroll.addView(rows);LinearLayout.LayoutParams scrollParams=new LinearLayout.LayoutParams(-1,dp(132));scrollParams.topMargin=dp(4);panel.addView(scroll,scrollParams);return panel;}
    private void showNekosGifPicker(){
        if(contact!=null&&contact.optBoolean("deleted")){toast("This archived conversation is read-only.");return;}
        LinearLayout layout=SereinUi.column(this);layout.setPadding(dp(10),dp(8),dp(10),dp(8));LinearLayout searchRow=SereinUi.row(this);gifSearch=new EditText(this);gifSearch.setSingleLine(true);gifSearch.setHint("Search GIFs");searchRow.addView(gifSearch,new LinearLayout.LayoutParams(0,dp(46),1));Button search=SereinUi.button(this,"Search",true);searchRow.addView(search,new LinearLayout.LayoutParams(dp(76),dp(42)));search.setOnClickListener(v->searchNekosGifs());layout.addView(searchRow);
        HorizontalScrollView categories=new HorizontalScrollView(this);categories.setHorizontalScrollBarEnabled(false);gifCategoryRow=new LinearLayout(this);gifCategoryRow.setOrientation(LinearLayout.HORIZONTAL);categories.addView(gifCategoryRow);layout.addView(categories,new LinearLayout.LayoutParams(-1,dp(44)));
        gifResultsScroll=new ScrollView(this);gifResults=new LinearLayout(this);gifResults.setOrientation(LinearLayout.VERTICAL);gifResultsScroll.addView(gifResults);layout.addView(gifResultsScroll,new LinearLayout.LayoutParams(-1,0,1));gifStatus=SereinUi.text(this,"GIF categories and results load from nekos.best.",10,SereinUi.muted(this),false);layout.addView(gifStatus);
        gifDialog=new Dialog(this);gifDialog.setTitle("GIF picker");gifDialog.setContentView(layout);gifDialog.setCancelable(true);gifDialog.show();if(gifDialog.getWindow()!=null)gifDialog.getWindow().setLayout(Math.min(getResources().getDisplayMetrics().widthPixels-dp(24),dp(560)),(int)(getResources().getDisplayMetrics().heightPixels*.78));
        gifResultsScroll.setOnScrollChangeListener((View view,int x,int y,int oldX,int oldY)->{View child=gifResultsScroll.getChildAt(0);if(child!=null&&y+gifResultsScroll.getHeight()>=child.getHeight()-dp(100))loadNekosGifBatch();});
        if(gifCategories.isEmpty())loadNekosCategories();else{renderNekosCategories();if(gifRows.isEmpty())loadNekosGifBatch();else renderNekosResults();}
    }
    private JSONObject requestNekosJson(String urlText)throws Exception{URL url=new URL(urlText);if(!"https".equals(url.getProtocol())||!"nekos.best".equalsIgnoreCase(url.getHost()))throw new SecurityException("Unexpected GIF provider URL.");HttpURLConnection connection=(HttpURLConnection)url.openConnection();connection.setConnectTimeout(10000);connection.setReadTimeout(15000);connection.setInstanceFollowRedirects(false);connection.setRequestProperty("Accept","application/json");try{int code=connection.getResponseCode();if(code<200||code>=300)throw new java.io.IOException("GIF service returned HTTP "+code);try(InputStream in=connection.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] buffer=new byte[8192];int n;while((n=in.read(buffer))!=-1){if(out.size()+n>2*1024*1024)throw new java.io.IOException("GIF response exceeded the safe size limit.");out.write(buffer,0,n);}return new JSONObject(new String(out.toByteArray(),StandardCharsets.UTF_8));}}finally{connection.disconnect();}}
    private void loadNekosCategories(){if(gifLoading)return;gifLoading=true;gifStatus.setText("Loading GIF categories…");gifExecutor.execute(()->{try{JSONObject payload=requestNekosJson("https://nekos.best/api/v2/endpoints");ArrayList<String> found=new ArrayList<>();String[] preferred={"hug","pat","wave","laugh","dance","smile"};Set<String> available=new HashSet<>();java.util.Iterator<String> keys=payload.keys();while(keys.hasNext()){String key=keys.next();if("gif".equalsIgnoreCase(payload.optJSONObject(key)==null?"":payload.optJSONObject(key).optString("format")))available.add(key);}for(String key:preferred)if(available.contains(key))found.add(key);if(found.isEmpty()){for(String key:available){found.add(key);if(found.size()==6)break;}}runOnUiThread(()->{gifLoading=false;gifCategories.clear();gifCategories.addAll(found);if(!gifCategories.contains(gifCategory)&&!gifCategories.isEmpty())gifCategory=gifCategories.get(0);renderNekosCategories();if(gifCategories.isEmpty())gifStatus.setText("No GIF categories are available.");else loadNekosGifBatch();});}catch(Exception error){runOnUiThread(()->{gifLoading=false;gifCategories.clear();gifCategories.addAll(java.util.Arrays.asList("hug","pat","wave","laugh","dance","smile"));renderNekosCategories();gifStatus.setText("Categories unavailable; try again or attach a local file.");});}});}
    private void renderNekosCategories(){if(gifCategoryRow==null)return;gifCategoryRow.removeAllViews();for(String value:gifCategories){Button pill=SereinUi.button(this,value.substring(0,1).toUpperCase(java.util.Locale.ROOT)+value.substring(1),value.equals(gifCategory)&&gifQuery.isEmpty());pill.setOnClickListener(v->{gifCategory=value;gifQuery="";if(gifSearch!=null)gifSearch.setText("");resetNekosResults();renderNekosCategories();loadNekosGifBatch();});gifCategoryRow.addView(pill,SereinUi.margin(this,-2,dp(36),0,3,4,3));}}
    private void resetNekosResults(){gifGeneration++;gifLoading=false;gifRows.clear();gifSeen.clear();gifPreviewRequested.clear();for(android.graphics.Bitmap bitmap:gifPreviewCache.values())bitmap.recycle();gifPreviewCache.clear();gifExhausted=false;gifRepeatedBatches=0;renderNekosResults();}
    private void searchNekosGifs(){String value=gifSearch==null?"":gifSearch.getText().toString().trim().replaceAll("\\s+"," ");if(value.isEmpty()){gifStatus.setText("Enter a search phrase.");return;}gifQuery=value.length()>80?value.substring(0,80):value;resetNekosResults();renderNekosCategories();loadNekosGifBatch();}
    private void loadNekosGifBatch(){
        if(gifLoading||gifExhausted||gifResults==null)return;gifLoading=true;if(gifStatus!=null)gifStatus.setText("Loading 15 GIFs…");String query=gifQuery,category=gifCategory;int generation=gifGeneration;
        gifExecutor.execute(()->{try{
            String endpoint=query.isEmpty()?category:"search";String url="https://nekos.best/api/v2/"+URLEncoder.encode(endpoint,"UTF-8")+"?type=2&amount=15"+(query.isEmpty()?"":"&query="+URLEncoder.encode(query,"UTF-8"));JSONObject payload=requestNekosJson(url);JSONArray rows=payload.optJSONArray("results");ArrayList<JSONObject> batch=new ArrayList<>();if(rows!=null)for(int i=0;i<rows.length();i++){JSONObject row=rows.optJSONObject(i);String image=row==null?"":row.optString("url","");if(isSafeNekosUrl(image))batch.add(row);}int count=rows==null?0:rows.length();
            runOnUiThread(()->{if(generation!=gifGeneration)return;gifLoading=false;int added=0;for(JSONObject row:batch){String image=row.optString("url","");if(gifSeen.add(image)){gifRows.add(row);added++;}}gifRepeatedBatches=added==0?gifRepeatedBatches+1:0;if(count<15||gifRepeatedBatches>=3||gifRows.size()>=120)gifExhausted=true;renderNekosResults();if(gifStatus!=null)gifStatus.setText((gifQuery.isEmpty()?gifCategory:"Search: "+gifQuery)+" · "+gifRows.size()+" GIFs · search terms and request metadata go to nekos.best.");});
        }catch(Exception error){runOnUiThread(()->{if(generation!=gifGeneration)return;gifLoading=false;if(gifStatus!=null)gifStatus.setText("Could not load GIFs. Try again or attach a local file.");});}});
    }
    private boolean isSafeNekosUrl(String value){try{URL url=new URL(value);return "https".equals(url.getProtocol())&&"nekos.best".equalsIgnoreCase(url.getHost())&&url.getPath().startsWith("/api/v2/");}catch(Exception ignored){return false;}}
    private void renderNekosResults(){
        if(gifResults==null)return;gifResults.removeAllViews();for(JSONObject result:gifRows){String url=result.optString("url"),title=result.optString("anime_name","GIF");LinearLayout tile=SereinUi.column(this);tile.setGravity(Gravity.CENTER);tile.setPadding(dp(6),dp(6),dp(6),dp(6));tile.setBackground(SereinUi.shape(this,SereinUi.surface(this),12));tile.setClickable(true);tile.setFocusable(true);ImageView preview=new ImageView(this);preview.setTag(url);preview.setScaleType(ImageView.ScaleType.CENTER_CROP);preview.setBackgroundColor(0xFFE5E9E8);tile.addView(preview,new LinearLayout.LayoutParams(-1,dp(105)));TextView label=SereinUi.text(this,(title.isEmpty()?"GIF":title)+" · Tap to send",11,SereinUi.text(this),true);label.setGravity(Gravity.CENTER);label.setMaxLines(2);tile.addView(label,SereinUi.margin(this,-1,-2,0,5,0,1));tile.setOnClickListener(v->downloadAndSendNekosGif(url,title));gifResults.addView(tile,SereinUi.margin(this,-1,-2,0,3,4,3));android.graphics.Bitmap cached=gifPreviewCache.get(url);if(cached!=null)preview.setImageBitmap(cached);else if(gifPreviewRequested.size()<24&&gifPreviewRequested.add(url))loadNekosPreview(url,preview);}if(gifRows.isEmpty()&&!gifLoading){TextView empty=SereinUi.text(this,"No GIF results yet.",12,SereinUi.muted(this),false);gifResults.addView(empty);}if(gifStatus!=null&&gifExhausted)gifStatus.setText("No more new GIFs in this result set.");
    }
    private void loadNekosPreview(String imageUrl,ImageView target){if(!isSafeNekosUrl(imageUrl))return;gifExecutor.execute(()->{try{HttpURLConnection connection=(HttpURLConnection)new URL(imageUrl).openConnection();connection.setConnectTimeout(8000);connection.setReadTimeout(10000);connection.setInstanceFollowRedirects(false);int code=connection.getResponseCode();String type=connection.getContentType();if(code<200||code>=300||type==null||!type.toLowerCase(java.util.Locale.ROOT).startsWith("image/")){connection.disconnect();return;}byte[] bytes;try(InputStream in=connection.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] buffer=new byte[8192];int n;while((n=in.read(buffer))!=-1){if(out.size()+n>900*1024)throw new java.io.IOException("Preview exceeds the size cap.");out.write(buffer,0,n);}bytes=out.toByteArray();}finally{connection.disconnect();}BitmapFactory.Options bounds=new BitmapFactory.Options();bounds.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(bytes,0,bytes.length,bounds);BitmapFactory.Options options=new BitmapFactory.Options();options.inSampleSize=Math.max(1,Math.min(bounds.outWidth/360,bounds.outHeight/240));android.graphics.Bitmap bitmap=BitmapFactory.decodeByteArray(bytes,0,bytes.length,options);if(bitmap!=null)runOnUiThread(()->{if(isFinishing()){bitmap.recycle();return;}gifPreviewCache.put(imageUrl,bitmap);if(imageUrl.equals(target.getTag()))target.setImageBitmap(bitmap);});}catch(Exception ignored){}});}
    private void downloadAndSendNekosGif(String imageUrl,String title){if(!isSafeNekosUrl(imageUrl)){toast("GIF provider returned an untrusted URL.");return;}if(gifStatus!=null)gifStatus.setText("Downloading GIF, then encrypting it as a Serein attachment…");gifExecutor.execute(()->{File saved=null;try{URL url=new URL(imageUrl);HttpURLConnection connection=(HttpURLConnection)url.openConnection();connection.setConnectTimeout(10000);connection.setReadTimeout(30000);connection.setInstanceFollowRedirects(false);int code=connection.getResponseCode();String type=connection.getContentType();if(code<200||code>=300||type==null||!type.toLowerCase(java.util.Locale.ROOT).startsWith("image/"))throw new java.io.IOException("GIF download failed validation.");saved=File.createTempFile("serein-nekos-",".gif",getCacheDir());try(InputStream in=connection.getInputStream();java.io.FileOutputStream out=new java.io.FileOutputStream(saved)){byte[] buffer=new byte[64*1024];int n;while((n=in.read(buffer))!=-1){if(saved.length()+n>SereinDeviceCrypto.MAX_FILE_CIPHERTEXT_BYTES)throw new java.io.IOException("GIF exceeds the 64 MiB encrypted attachment limit.");out.write(buffer,0,n);}out.flush();out.getFD().sync();}finally{connection.disconnect();}if(saved.length()<=0)throw new java.io.IOException("GIF download was empty.");File file=saved;runOnUiThread(()->{if(gifDialog!=null)gifDialog.dismiss();status.setText("Preparing encrypted GIF attachment…");engine.uploadAttachment(file,file.getName(),"image/gif").whenComplete((ignored,error)->runOnUiThread(()->{file.delete();status.setText(error==null?engine.status():safeError(error));render();}));});}catch(Exception error){if(saved!=null)saved.delete();runOnUiThread(()->{if(gifStatus!=null)gifStatus.setText("GIF could not be sent securely. Try a different result.");});}});}
