        TextView meta=SereinUi.text(this,mine?deliverySummary(row):formatEventDate(row.optString("created_at")),10,mine&&SereinUi.isDark(this)?0xFFB9D9D0:SereinUi.muted(this),false);meta.setGravity(Gravity.END);bubble.addView(meta);
